#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$SCRIPT_DIR/common.sh"

print_header "Configuring MAME"

ensure_dir "$MAME_ROOT"
ensure_dir "$MAME_ROMS_DIR"
ensure_dir "$MAME_ARTWORK_DIR"
ensure_dir "$MAME_SAMPLES_DIR"
ensure_dir "$MAME_CONFIG_DIR"

cat > "$MAME_ROOT/mame.ini" <<EOF
# Generated by $SCRIPT_DIR/configure_mame.sh
rompath $MAME_ROMS_DIR
samplepath $MAME_SAMPLES_DIR
artpath $MAME_ARTWORK_DIR
cfg_directory $MAME_CONFIG_DIR
nvram_directory $MAME_ROOT/nvram
input_directory $MAME_ROOT/input
state_directory $MAME_ROOT/state
skip_gameinfo 1
EOF

cat <<EOF
MAME is configured with these base directories:
- ROMs: $MAME_ROMS_DIR
- Artwork: $MAME_ARTWORK_DIR
- Samples: $MAME_SAMPLES_DIR
- Config: $MAME_CONFIG_DIR
- ini: $MAME_ROOT/mame.ini
EOF
